CREATE SET TABLE MDP01_META.META_ETL_JOB_STEP_RUN ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      etl_job_step_run_id BIGINT NOT NULL GENERATED ALWAYS AS IDENTITY           (START WITH 1             INCREMENT BY 1             MINVALUE -999999999999999999             MAXVALUE 999999999999999999             NO CYCLE),      etl_job_run_id INTEGER NOT NULL,      etl_job_step_id BIGINT NOT NULL,      start_time TIMESTAMP(6),      end_time TIMESTAMP(6),      duration_seconds DECIMAL(10,2),      status VARCHAR(20) CHARACTER SET LATIN CASESPECIFIC NOT NULL,      exit_code INTEGER,      rows_read BIGINT,      rows_inserted BIGINT,      rows_updated BIGINT,      rows_deleted BIGINT,      rows_rejected BIGINT,      cpu_time_seconds DECIMAL(10,2),      io_operations BIGINT,      temp_space_mb DECIMAL(18,2),      error_message VARCHAR(4000) CHARACTER SET LATIN CASESPECIFIC,      error_stacktrace CLOB(16777216) CHARACTER SET UNICODE,      error_line_number INTEGER,      executed_sql CLOB(16777216) CHARACTER SET UNICODE,      execution_user VARCHAR(200) CHARACTER SET LATIN CASESPECIFIC DEFAULT USER ,      execution_host VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC,      was_skipped CHAR(1) CHARACTER SET LATIN CASESPECIFIC CHECK ( was_skipped  IN ('Y','N') ) DEFAULT 'N',      skip_reason VARCHAR(500) CHARACTER SET LATIN CASESPECIFIC,      create_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6))PRIMARY INDEX ( etl_job_step_run_id );